<?php
require_once __DIR__ . '/../../../App/auth.php';require_login();$pdo=db();$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT d.*,e.id_especialista,td.nome tipo_documento FROM documentos d JOIN especialistas e ON e.id_especialista=d.id_especialista JOIN tipos_documento td ON td.id_tipo_documento=d.id_tipo_documento WHERE d.id_documento=?");$st->execute([$id]);$doc=$st->fetch();if(!$doc){header('Location: especialistas.php');exit;}$tipos=$pdo->query("SELECT id_tipo_documento,nome FROM tipos_documento WHERE estado='ATIVO' ORDER BY nome")->fetchAll();$erro='';
if($_SERVER['REQUEST_METHOD']==='POST'){$tipo=(int)($_POST['id_tipo_documento']??0);$titulo=trim($_POST['titulo']??'');$dd=$_POST['data_documento']?:null;$dv=$_POST['data_validade']?:null;$desc=trim($_POST['descricao']??'');if(!$tipo||$titulo==='')$erro='Informe o tipo e o título.';elseif($dd&&$dv&&$dv<$dd)$erro='A validade não pode ser anterior à data do documento.';else{$up=$pdo->prepare("UPDATE documentos SET id_tipo_documento=?,titulo=?,data_documento=?,data_validade=?,descricao=? WHERE id_documento=?");$up->execute([$tipo,$titulo,$dd,$dv,$desc,$id]);header('Location: especialista.php?id='.(int)$doc['id_especialista'].'#documentos');exit;}}
$page_title='Editar Documento';require __DIR__.'/../../layout/header.php';?>
<div class="module-page"><div class="panel form-panel"><h2>Editar documento</h2><p><strong><?=htmlspecialchars($doc['nome_ficheiro'])?></strong></p><?php if($erro):?><div class="erro"><?=htmlspecialchars($erro)?></div><?php endif;?><form method="post" class="form-grid"><label>Tipo<select name="id_tipo_documento" required><?php foreach($tipos as $t):?><option value="<?=$t['id_tipo_documento']?>" <?=$doc['id_tipo_documento']==$t['id_tipo_documento']?'selected':''?>><?=htmlspecialchars($t['nome'])?></option><?php endforeach;?></select></label><label>Título<input name="titulo" value="<?=htmlspecialchars($doc['titulo'])?>" required></label><label>Data do documento<input type="date" name="data_documento" value="<?=htmlspecialchars($doc['data_documento']??'')?>"></label><label>Data de validade<input type="date" name="data_validade" value="<?=htmlspecialchars($doc['data_validade']??'')?>"></label><label class="full">Descrição<textarea name="descricao" rows="4"><?=htmlspecialchars($doc['descricao']??'')?></textarea></label><div class="actions full"><button class="btn btn-primary">Guardar</button><a class="btn btn-secondary" href="especialista.php?id=<?=(int)$doc['id_especialista']?>#documentos">Cancelar</a></div></form></div></div>
<?php require __DIR__.'/../../layout/footer.php'; ?>
